    return invalid;
  if (
    !Array.isArray(matches) ||
    matches.length !== names.length - 1 ||
    !Number.isInteger(current) ||
    typeof current !== 'number' ||
    current < 0 ||
    current >= matches.length ||
    !['ready', 'playing', 'turn-ended', 'match-ended', 'champion'].includes(String(phase))
