  let expected = newTournament(names, codes);
  for (let i = 0; i <= current; i++) {
    const match = matches[i] as Record<string, unknown>;
    const results = match.results as [unknown, unknown];
    if (i < current && (!results[0] || !results[1])) return invalid;
    if (results[1] && !results[0]) return invalid;
    expected = { ...expected, current: i };
    if (results[0])
      expected = finishTurn(
        expected,
        results[0] as NonNullable<Tournament['matches'][number]['results'][number]>,
      );
    if (results[1])
      expected = finishTurn(
        expected,
        results[1] as NonNullable<Tournament['matches'][number]['results'][number]>,
      );
  }
  for (let i = 0; i < matches.length; i++) {
    const actual = matches[i] as Record<string, unknown>;
    const match = expected.matches[i]!;
    if (
      JSON.stringify(actual.players) !== JSON.stringify(match.players) ||
      actual.winner !== match.winner ||
      JSON.stringify(actual.results) !== JSON.stringify(match.results)
    ) {
      // Result object property order is immaterial.
      const r = actual.results as Array<{ moves: number; elapsedMs: number } | null>;
