  return (
    Object.keys(v).sort().join(',') === 'elapsedMs,moves' &&
    typeof v.moves === 'number' &&
    Number.isSafeInteger(v.moves) &&
    v.moves >= (size * size) / 2 &&
    v.moves <= MOVES_MAX &&
    typeof v.elapsedMs === 'number' &&
    Number.isFinite(v.elapsedMs) &&
    v.elapsedMs >= 0 &&
    v.elapsedMs <= ELAPSED_MAX_MS
